$token = "YOUR_GITHUB_TOKEN_HERE"
$sha = "4daed03c83dec7e8ad116dfb25fd5bcf6613fb6b"
$headers = @{
    "Authorization" = "token $token"
    "Accept" = "application/vnd.github+json"
    "Content-Type" = "application/json"
}
$content = ""
$body = @{ message="v7: 94rooms + camera modal + customer file tab + CS tab"; content=$content; sha=$sha } | ConvertTo-Json -Depth 3
$res = Invoke-RestMethod -Method Put -Uri "https://api.github.com/repos/beefree10/seri47/contents/index.html" -Headers $headers -Body $body
Write-Host "Deployed: $($res.content.name) — SHA: $($res.content.sha)"
